&lt;p data-renderer-start-pos=&quot;662&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Privacy and AI Guidelines:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;662&quot;&gt;Any information you submit to Datadog as part of your application will be processed in accordance with Datadog’s&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://www.datadoghq.com/legal/applicant-candidate-privacy/&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.datadoghq.com/legal/applicant-candidate-privacy/&quot; data-sk=&quot;tooltip_parent&quot;&gt;Applicant and Candidate Privacy Notice&lt;/a&gt;. For information on our AI policy, please visit &lt;a href=&quot;https://www.datadoghq.com/legal/interviewing-at-datadog-ai-guidelines/&quot; target=&quot;_blank&quot;&gt;Interviewing at Datadog AI Guidelines&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;", "departments": [{"id": 202107, "name": "Enterprise Sales Engineering", "child_ids": [], "parent_id": 9023}], "offices": [{"id": 5455, "name": "Boston", "location": "Boston, MA, United States", "child_ids": [], "parent_id": 78117}, {"id": 5664, "name": "New York", "location": "New York, NY, United States", "child_ids": [81327, 76746], "parent_id": 73429}, {"id": 57627, "name": "San Francisco", "location": "San Francisco, CA, United States", "child_ids": [], "parent_id": 78108}], "ai_disclaimer": null, "include_ai_disclaimer": null, "ai_opt_out_request_url": null}]}
